<?php
$page_title = 'Accesos de Usuario T-TI-F-08';
require_once(__DIR__ . '/../../includes/load.php');
require_once(__DIR__ . '/../../config/app.php');
require_once(__DIR__ . '/funciones.php');
require_permiso('accesos_usuario', 'ver');
$focusUserId = max(0, (int)($_GET['user_id'] ?? 0));

$records = find_by_sql("SELECT f.*,u.`name` AS usuario_actual,u.`area`,u.`subarea`,u.`status` AS usuario_estado,
  m.`Host` AS host_actual,m.`Tipo_Activo`,m.`EstadoMaquina`
  FROM `usuariosf08` f
  LEFT JOIN `users` u ON u.`id`=f.`user_id`
  LEFT JOIN `maquina` m ON m.`IdMaquina`=f.`maquina_id`
  ORDER BY f.`estado_f8` DESC,f.`FechaRegistro` DESC,f.`ID_Usuariosf08` DESC");

$summary = ['total' => count($records), 'active' => 0, 'sap' => 0, 'pending_link' => 0];
foreach ($records as $row) {
    if ((int)$row['estado_f8'] === 1) $summary['active']++;
    if ((int)$row['estado_f8'] === 1 && f08_yes($row['sap_f8'])) $summary['sap']++;
    if (empty($row['user_id']) || empty($row['maquina_id'])) $summary['pending_link']++;
}
$focusName = '';
if ($focusUserId > 0) {
    foreach ($records as $row) {
        if ((int)$row['user_id'] === $focusUserId) {
            $focusName = (string)$row['NomApe'];
            break;
        }
    }
}

$extraCss = ['https://fonts.googleapis.com/css2?family=Manrope:wght@500;600;700;800&display=swap'];
$recordsJson = json_encode($records, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT);
include_once(__DIR__ . '/../../layouts/header.php');
?>
