 $.fn.dataTable.ext.search.push(function(settings,data,index){if(settings.nTable.id!=='tblF08')return true;var row=table.row(index).node();var status=$('#f08Status').val();var system=$('#f08System').val();return(!f08FocusUser||Number(row.getAttribute('data-user-id'))===f08FocusUser)&&(!status||row.getAttribute('data-status')===status)&&(!system||(row.getAttribute('data-system')||'').indexOf(system)!==-1)});
 if(f08FocusUser)$('#f08Status').val('');table.draw();$('#f08Status,#f08System').on('change',function(){table.draw()});$('#f08Search').on('input',function(){table.search(this.value).draw()});$('#f08Excel').on('click',function(){table.button(0).trigger()});
 function esc(v){return $('<div>').text(v==null?'':String(v)).html()}function value(v){return v&&String(v).trim()&&v!=='-'?esc(v):'<span class="f08-empty">No registrado</span>'}function yes(v){return ['SI','S','1','YES'].indexOf(String(v||'').trim().toUpperCase())!==-1}
 function pair(label,val){return'<label>'+esc(label)+'</label><strong>'+value(val)+'</strong>'}
 function appCard(name,enabled,user,role){return'<div class="f08-app-card '+(enabled?'on':'')+'"><b><i class="fas '+(enabled?'fa-check-circle text-success':'fa-minus-circle text-muted')+' mr-1"></i>'+esc(name)+'</b><small>'+(enabled?('Usuario: '+(esc(user)||'No indicado')+'<br>Perfil: '+(esc(role)||'No indicado')):'Sin acceso')+'</small></div>'}
 function folderTags(value,icon){var raw=String(value||'').trim();if(!raw)return'<span class="f08-empty">Sin carpetas asignadas</span>';var items=raw.split(/\s*[,;\n]\s*|\s*-\s*(?=(?:[1-5]\.\d{2}|Vault))/i).map(function(item){return item.trim()}).filter(Boolean);return'<div class="f08-folder-tags">'+items.map(function(item){return'<span class="f08-folder-tag"><i class="fas '+icon+'"></i>'+esc(item)+'</span>'}).join('')+'</div>'}
 function emailSize(bytes){var size=Number(bytes||0);return size<1024?size+' B':(size<1048576?(size/1024).toFixed(1)+' KB':(size/1048576).toFixed(1)+' MB')}
 function loadEmails(id,name){var box=$('#f08EmailWindow');$('#f08EmailTitle').text('Correos de '+name);$('#f08EmailEdit').attr('href','formulario.php?id='+id+'#correos');box.html('<div class="f08-email-empty"><i class="fas fa-spinner fa-spin mr-1"></i>Cargando historial...</div>');$('#modalF08Correos').modal('show');fetch('correos.php?action=list&registro_id='+encodeURIComponent(id),{credentials:'same-origin'}).then(function(response){return response.json().then(function(json){if(!response.ok)throw new Error(json.error||'No se pudo consultar.');return json})}).then(function(data){var rows=data.rows||[];if(!rows.length){box.html('<div class="f08-email-empty"><i class="far fa-envelope-open fa-2x mb-2 d-block"></i>No hay correos archivados en esta ficha.</div>');return}box.html(rows.map(function(item){var active=item.estado==='VALIDO';return'<div class="f08-email-row '+(active?'':'inactive')+'"><div class="f08-email-file"><i class="fas '+(item.extension==='pdf'?'fa-file-pdf':'fa-envelope')+'"></i></div><div class="f08-email-data"><strong>'+esc(item.asunto||item.nombre_original)+'</strong><span>'+esc(item.nombre_original)+' &middot; '+emailSize(item.tamano_bytes)+'</span><span>Subido el '+esc(item.fecha_carga)+' por '+esc(item.cargado_por_nombre||'Sistema')+'</span>'+(item.descripcion?'<span>'+esc(item.descripcion)+'</span>':'')+'<span class="f08-email-badge">'+(active?'V&Aacute;LIDO':'INACTIVO')+'</span></div><a class="btn btn-outline-info" target="_blank" href="correos.php?action=download&id='+Number(item.id)+'" title="Abrir o descargar"><i class="fas fa-external-link-alt"></i></a></div>'}).join(''))}).catch(function(error){box.html('<div class="alert alert-danger mb-0">'+esc(error.message)+'</div>')})}
 $(document).on('click','.btnCorreosF08',function(){loadEmails(Number($(this).data('id')),String($(this).data('name')||'la ficha'))});
 function previewPair(label,value){return'<label>'+esc(label)+'</label><strong>'+(value?esc(value):'<span class="text-muted">No indicado</span>')+'</strong>'}
 function previewAttachments(items){if(!items||!items.length)return'<span class="text-muted">Sin adjuntos</span>';return'<div class="d-flex flex-wrap" style="gap:6px">'+items.map(function(item){if(typeof item==='string')return'<span class="badge badge-light border">'+esc(item)+'</span>';return'<a class="btn btn-sm btn-outline-info" href="'+esc(item.url)+'" title="Descargar adjunto"><i class="fas fa-paperclip mr-1"></i>'+esc(item.name)+'</a>'}).join('')+'</div>'}
 function previewEmail(id){var content=$('#f08PreviewContent'),download='correos.php?action=download&id='+id;$('#f08PreviewDownload').attr('href',download);$('#f08PreviewTitle').text('Cargando correo...');content.html('<div class="f08-email-empty"><i class="fas fa-spinner fa-spin mr-1"></i>Interpretando el archivo...</div>');$('#modalF08CorreoPreview').modal('show');fetch('correos.php?action=preview&id='+encodeURIComponent(id),{credentials:'same-origin'}).then(function(response){return response.json().then(function(json){if(!response.ok)throw new Error(json.error||'No se pudo visualizar.');return json})}).then(function(data){if(data.type==='pdf'){$('#f08PreviewTitle').text('Documento PDF');content.html('<iframe class="f08-preview-frame" src="'+esc(data.url)+'"></iframe>');return}var mail=data.content||{};$('#f08PreviewTitle').text(mail.subject||'Correo archivado');content.html('<div class="f08-preview-meta">'+previewPair('De',mail.sender)+previewPair('Para',mail.to)+previewPair('CC',mail.cc)+previewPair('Fecha',mail.date)+'<label>Adjuntos</label><strong>'+previewAttachments(mail.attachments||[])+'</strong></div><div class="f08-preview-body">'+esc(mail.body||'El correo no contiene texto visible.')+'</div>')}).catch(function(error){content.html('<div class="alert alert-danger mb-0">'+esc(error.message)+'</div>')})}
 $(document).on('mouseenter focus','#f08EmailWindow a[href*="action=download"]',function(){$(this).attr('title','Visualizar correo').find('i').attr('class','fas fa-eye')});
 $(document).on('click','#f08EmailWindow a[href*="action=download"]',function(event){event.preventDefault();var match=String(this.href).match(/[?&]id=(\d+)/);if(match)previewEmail(Number(match[1]))});
 $('#modalF08CorreoPreview').on('shown.bs.modal',function(){$('.modal-backdrop').last().css('z-index',1060)}).on('hidden.bs.modal',function(){if($('#modalF08Correos').hasClass('show'))$('body').addClass('modal-open')});
 $(document).on('click','.btnVerF08',function(){var id=Number($(this).data('id'));var r=f08Records.find(function(x){return Number(x.ID_Usuariosf08)===id});if(!r)return;
  $('#f08DetailTitle').text('F08-'+String(id).padStart(4,'0')+' - '+r.NomApe);
  $('#f08Identity').html(pair('Colaborador',r.NomApe)+pair('Cargo',r.Cargo)+pair('Cuenta Samba',r.UsuarioTamadom)+pair('Correo',r.Correo)+pair('Equipo actual',r.host_actual||'Sin vinculo')+pair('Equipo registrado',r.NumPC)+pair('Fecha de labores',r.FechaLabores));
  $('#f08Controls').html(pair('Tipo de registro',r.TipoRegis)+pair('Fecha de registro',r.FechaRegistro)+pair('Navegacion',r.ninavega_f8)+pair('Nivel de correo',r.nivcorr_f8)+pair('Correo puente',r.corrpuen_f8)+pair('USB',yes(r.ausb_f8)?'Permitido':'No permitido')+pair('Correo en celular',yes(r.corrcelu_f8)?'Si':'No')+pair('Software basico',yes(r.softwarebasi_f8)?'Instalado':'No'));
   $('#f08FoldersWrite').html(folderTags(r.CarpetasCompartidasM,'fa-pen'));$('#f08FoldersRead').html(folderTags(r.CarpetasCompartidasV,'fa-eye'));
  $('#f08Apps').html(appCard('SAP Business One',yes(r.sap_f8),r.ususap_f8,r.saplicen_f8)+appCard('Requerimientos RCO',yes(r.requerimient_f8),r.usureque_f8,r.requeutili_f8)+appCard('Orbis',yes(r.orbis_f8),r.usuorb_f8,r.utilidadorb_f8)+appCard('App TAMA',yes(r.apptam_f8),r.usuapptam_f8,r.utilidapptam_f8));
  $('#f08Notes').html(value(r.Observaciones));$('#f08History').html('<i class="fas fa-spinner fa-spin mr-1"></i>Cargando historial...');$('#f08EditLink').attr('href','formulario.php?id='+id);$('#modalF08Detalle').modal('show');
  fetch('historial.php?id='+encodeURIComponent(id),{credentials:'same-origin'}).then(function(response){return response.json()}).then(function(data){var rows=data.rows||[];if(!rows.length){$('#f08History').html('<span class="f08-empty">Aun no hay movimientos registrados.</span>');return}$('#f08History').html(rows.map(function(item){return'<div class="d-flex justify-content-between border-bottom py-2"><div><strong>'+esc(item.accion)+'</strong><div>'+value(item.detalle)+'</div></div><div class="text-right ml-3"><span>'+esc(item.created_at)+'</span><div>'+esc(item.registrado_por_nombre||'Sistema')+'</div></div></div>'}).join(''))}).catch(function(){$('#f08History').text('No se pudo cargar el historial.')});
 });
 $(document).on('submit','.formEstadoF08',function(e){if($(this).data('confirmed'))return;e.preventDefault();var form=this;var activate=$(this).find('[name=estado]').val()==='1';Swal.fire({title:activate?'Reactivar esta ficha?':'Desactivar esta ficha?',text:activate?'El acceso volvera a mostrarse como vigente.':'Se conserva todo el historial; no se eliminara informacion.',icon:'warning',showCancelButton:true,confirmButtonText:activate?'Si, reactivar':'Si, desactivar',cancelButtonText:'Cancelar',confirmButtonColor:activate?'#168057':'#c03946'}).then(function(r){if(r.isConfirmed){$(form).data('confirmed',true);form.submit()}})});
});
